// ============================================================
// generator.js — Builds complete loyalty portal HTML from state
// ============================================================

function generatePortalHTML(s) {
  const view = typeof window !== 'undefined' && window.LPGProgramRuntime && window.LPGProgram
    ? window.LPGProgramRuntime.projectState(s, window.LPGProgram) : s;
  let html = generateClassicPortalHTML(view);
  if (typeof window !== 'undefined' && window.LPGProgramRuntime) html = window.LPGProgramRuntime.enhance(html, s);
  if (typeof window !== 'undefined' && window.PortalTemplates) html = window.PortalTemplates.apply(html, view);
  return html;
}

function lpgEscape(value) {
  return String(value == null ? '' : value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}


// These helpers keep customer content in its intended HTML, URL, or CSS context.
// Image data is rendered only in image contexts, never as inline document markup.
function lpgImageSource(value) {
  const source = String(value == null ? '' : value).trim();
  return /^(?:https?:\/\/[^/\s?#]+(?:[/?#][^\u0000-\u001f\u007f]*)?|data:image\/(?:png|jpe?g|webp|gif|avif|svg\+xml)(?:;base64)?,[\s\S]+)$/i.test(source) ? source : '';
}
function lpgLocale(s) { try{return Intl.getCanonicalLocales(s._program?.locale || s.locale || 'en-US')[0] || 'en-US';}catch{return 'en-US';} }
function lpgLabel(s,key,fallback) { return lpgEscape(typeof s.displayLabels?.[key]==='string'?s.displayLabels[key]:fallback); }
function lpgImageStyle(item,prefix='image') {
  const fit=item?.[prefix+'Fit']==='contain'?'contain':'cover';
  const values=String(item?.[prefix+'Position']||'50% 50%').split(' ').map(n=>Math.max(0,Math.min(100,parseFloat(n)||0)));
  return `object-fit:${fit};object-position:${values[0]??50}% ${values[1]??50}%;`;
}
function lpgColor(value, fallback = '#243447') {
  const color = String(value || '');
  if (/^#[a-f0-9]{6}$/i.test(color)) return color;
  if (/^#[a-f0-9]{3}$/i.test(color)) return '#' + color.slice(1).split('').map(c => c+c).join('');
  // Preserve the translucent text colors offered by the upsell editor.
  if (/^rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}(?:\s*,\s*(?:0|1|0?\.\d+))?\s*\)$/i.test(color)) return color;
  return fallback;
}
function lpgGradient(value, fallback) {
  const token = item => /^(?:slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-(?:50|[1-9]00|950)$/.test(String(item || ''));
  return Array.isArray(value) && value.length === 2 && value.every(token) ? value : fallback;
}
function lpgNumber(value) { const number = Number(value); return Number.isFinite(number) ? number : 0; }
function lpgPercent(value) { return Math.max(0, Math.min(100, lpgNumber(value))); }
function lpgCssImage(value) {
  // CSS string escaping is separate from the surrounding HTML attribute escaping.
  return lpgImageSource(value).replace(/[\\"'()\s<>]/g, c => '%' + c.charCodeAt(0).toString(16).padStart(2, '0'));
}

// RGB channels allow compiled utilities such as ring-primary/30 to retain
// their opacity modifiers while each export uses its own customer palette.
function lpgPortalThemeVariables(colors, primaryLight, accentDark, menu, menuLight) {
  const values = {
    primary: colors.primary, 'primary-light': primaryLight, secondary: colors.secondary,
    accent: colors.accent, 'accent-dark': accentDark, menu, 'menu-light': menuLight,
    dark: colors.dark, light: '#ffffff', success: '#22c55e', warning: '#f59e0b',
    danger: '#ef4444', muted: '#6b7280', border: '#e5e7eb', card: '#ffffff', 'page-bg': '#f5f6f8'
  };
  return Object.entries(values).map(([name,value]) => {
    let hex = /^#[a-f0-9]{3}(?:[a-f0-9]{3})?$/i.test(value || '') ? value.slice(1) : '243447';
    if (hex.length === 3) hex = hex.split('').map(c => c+c).join('');
    const rgb = [0,2,4].map(i => parseInt(hex.slice(i,i+2),16)).join(' ');
    return '--portal-' + name + '-rgb: ' + rgb + ';';
  }).join('\n      ');
}

function generateClassicPortalHTML(s) {
  s = { ...s, colors: Object.fromEntries(Object.entries(s.colors || {}).map(([key, value]) => [key, lpgColor(value)])) };
  const esc = lpgEscape;
  const primaryLight = lightenColor(s.colors.primary, 20);
  const accentDark = darkenColor(s.colors.accent, 15);
  const menuColor = s.colors.menu || s.colors.primary;
  const menuColorLight = lightenColor(menuColor, 10);
  const programName = s.brand.programName || 'My Loyalty Perks';
  const brandAbbr = (s.brand.name || 'MY').split(' ').map(w=>w[0]||'').join('').toUpperCase().slice(0,3) || 'MY';
  const logoSrc = lpgImageSource(s.brand.logoData || s.brand.logoUrl);
  const avatarSrc = lpgImageSource(s.member.avatarData || s.member.avatarUrl);
  const pointsToNext = s.tiers[1] ? Math.max(0, s.tiers[1].points - (s.member.points||0)) : 0;

  return `<!DOCTYPE html>
<html lang="${lpgEscape(lpgLocale(s))}" dir="${/^(ar|he|fa|ur)(-|$)/.test(lpgLocale(s))?'rtl':'ltr'}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${esc(programName)} — Loyalty Portal</title>
  <style id="lpg-portal-utilities">${LPG_PORTAL_UTILITIES_CSS}</style>
  <style id="lpg-portal-theme">
    :root {
      ${lpgPortalThemeVariables(s.colors, primaryLight, accentDark, menuColor, menuColorLight)}
    }
    :root {
      --brand-primary: ${lpgColor(s.colors.primary)};
      --brand-primary-light: ${primaryLight};
      --brand-accent: ${lpgColor(s.colors.accent)};
      --brand-menu: ${menuColor};
      --brand-dark: ${lpgColor(s.colors.dark)};
    }
    body { font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; -webkit-font-smoothing: antialiased; }
    .site-header { background-color: ${menuColor} !important; box-shadow: 0 2px 12px rgba(0,0,0,0.08), 0 1px 3px rgba(0,0,0,0.06); }
    .toggle-content { max-height: 0; overflow: hidden; transition: max-height 0.4s ease-out, opacity 0.3s ease-out; opacity: 0; }
    .toggle-content.open { max-height: 2000px; opacity: 1; transition: max-height 0.5s ease-in, opacity 0.3s ease-in; }
    .chevron-icon { transition: transform 0.3s ease; }
    .chevron-icon.rotated { transform: rotate(180deg); }
    .card { background: #fff; border-radius: 14px; border: 1px solid #EAECEF; box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
    .card-hover { transition: box-shadow 0.25s ease, transform 0.25s ease, border-color 0.25s ease; }
    .card-hover:hover { box-shadow: 0 10px 24px -8px rgba(16,24,40,0.12), 0 4px 8px -4px rgba(16,24,40,0.06); transform: translateY(-2px); border-color: rgba(0,0,0,0.08); }
    .voucher-card { transition: box-shadow 0.25s ease, transform 0.25s ease, border-color 0.25s ease; }
    .voucher-card:hover { box-shadow: 0 10px 24px -8px rgba(16,24,40,0.12), 0 4px 8px -4px rgba(16,24,40,0.06); transform: translateY(-2px); border-color: rgba(0,0,0,0.08); }
    .offer-card { transition: box-shadow 0.25s ease, transform 0.25s ease, border-color 0.25s ease; }
    .offer-card:hover { box-shadow: 0 14px 30px -10px rgba(16,24,40,0.14), 0 6px 12px -6px rgba(16,24,40,0.08); transform: translateY(-2px); }
    .earn-card { transition: box-shadow 0.25s ease, border-color 0.25s ease, transform 0.25s ease; }
    .earn-card:hover { box-shadow: 0 6px 16px -6px rgba(16,24,40,0.10); border-color: ${lpgColor(s.colors.primary)}30; transform: translateY(-1px); }
    .badge-ring { box-shadow: 0 0 0 3px #fff, 0 0 0 5px currentColor, 0 8px 18px -8px rgba(16,24,40,0.35); }
    .member-hero { background: linear-gradient(135deg, ${lpgColor(s.colors.primary)} 0%, ${darkenColor(s.colors.primary, 8)} 55%, ${lightenColor(s.colors.primary, 8)} 100%); position: relative; overflow: hidden; }
    .member-hero::before { content: ''; position: absolute; inset: 0; background-image: radial-gradient(circle at 85% 15%, rgba(255,255,255,0.10) 0%, transparent 45%), radial-gradient(circle at 15% 90%, rgba(255,255,255,0.08) 0%, transparent 40%); pointer-events: none; }
    .btn-primary { background: ${lpgColor(s.colors.primary)}; color: #fff; transition: background 0.2s ease, transform 0.15s ease, box-shadow 0.2s ease; box-shadow: 0 2px 8px -2px ${lpgColor(s.colors.primary)}55; }
    .btn-primary:hover { background: ${primaryLight}; transform: translateY(-1px); box-shadow: 0 6px 16px -4px ${lpgColor(s.colors.primary)}66; }
    .btn-ghost { background: transparent; color: ${lpgColor(s.colors.primary)}; border: 1.5px solid ${lpgColor(s.colors.primary)}; transition: background 0.2s ease, color 0.2s ease; }
    .btn-ghost:hover { background: ${lpgColor(s.colors.primary)}; color: #fff; }
    .nav-link { position: relative; }
    .nav-link::after { content: ''; position: absolute; left: 50%; bottom: -6px; width: 0; height: 2px; background: ${lpgColor(s.colors.accent)}; transition: width 0.25s ease, left 0.25s ease; }
    .nav-link:hover::after { width: 100%; left: 0; }
    .section-title { font-weight: 800; letter-spacing: -0.01em; }
    .divider-gradient { background: linear-gradient(90deg, transparent, ${lpgColor(s.colors.primary)}20, transparent); height: 1px; }
  </style>
</head>
<body class="bg-page-bg text-dark min-h-screen">

${buildHeader(s, logoSrc, programName, brandAbbr, menuColor)}

<main class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
  <div class="flex items-end justify-between mb-6">
    <h1 class="text-3xl font-800 text-dark section-title">${esc(programName)}</h1>
  </div>

${buildMemberCard(s)}
${buildTierProgress(s, pointsToNext)}
${buildProfile(s)}
${buildBenefits(s)}

  <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
    <div class="lg:col-span-2 space-y-6">
${s.sections.vouchers ? buildVouchers(s) : ''}
${s.sections.offers ? buildOffers(s) : ''}
${s.sections.earnMore ? buildEarnMore(s) : ''}
    </div>
    <div class="space-y-6">
${s.sections.profileTasks ? buildProfileTasks(s) : ''}
${s.sections.badges ? buildBadges(s) : ''}
${s.sections.clubs ? buildClubs(s) : ''}
${s.sections.upsell ? buildUpsell(s) : ''}
    </div>
  </div>
</main>

${buildFooter(s, programName, brandAbbr)}
${buildScript()}
</body>
</html>`;
}

// ---- HEADER ----
function buildHeader(s, logoSrc, programName, brandAbbr, menuColor) {
  menuColor = lpgColor(menuColor);
  logoSrc = lpgImageSource(logoSrc);
  const navLinks = (s.navLinks||[]).map(n =>
    `<a href="#" class="nav-link text-white/90 hover:text-white text-sm font-600 transition-colors">${lpgEscape(n)}</a>`
  ).join('\n            ');

  const rawName = (s.brand.name && s.brand.name.trim()) || 'Loyalty';
  const displayName = lpgEscape(rawName);
  const logoHTML = logoSrc
    ? `<img src="${lpgEscape(logoSrc)}" alt="${displayName}" class="h-10 w-auto object-contain" onerror="this.style.display='none';this.nextElementSibling.style.display='inline-flex';">
          <span class="text-xl font-800 tracking-tight text-white hidden" style="display:none;">${displayName}</span>`
    : `<span class="text-xl font-800 tracking-tight text-white">${displayName}</span>`;

  const menuAccent = lpgColor(s.colors.accent, '#4299E1');

  return `<header class="site-header sticky top-0 z-50" style="background-color: ${menuColor}; background-image: linear-gradient(180deg, ${lightenColor(menuColor, 3)} 0%, ${menuColor} 100%);">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="flex items-center justify-between h-16">
        <a href="#" class="flex items-center gap-2 shrink-0">
          ${logoHTML}
        </a>
        <nav class="hidden md:flex items-center gap-7">
            ${navLinks}
        </nav>
        <div class="flex items-center gap-3">
          <button class="hidden md:flex w-9 h-9 rounded-full items-center justify-center text-white/80 hover:text-white hover:bg-white/10 transition-colors" title="Search">
            <svg class="w-4.5 h-4.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="width: 18px; height: 18px;"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
          </button>
          <button class="md:hidden text-white"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 6h16M4 12h16M4 18h16"/></svg></button>
          <div class="w-9 h-9 rounded-full flex items-center justify-center cursor-pointer ring-2 ring-white/20 hover:ring-white/40 transition-all" style="background-color: ${menuAccent};" title="Account">
            <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 24 24" style="color: ${menuColor};"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>
          </div>
        </div>
      </div>
    </div>
  </header>`;
}

// ---- MEMBER CARD ----
function buildMemberCard(s) {
  const avatarSrc = lpgImageSource(s.member.avatarData || s.member.avatarUrl);
  const initials = (s.member.name||'M').split(' ').map(w=>w[0]||'').join('').toUpperCase().slice(0,2) || 'M';
  const avatarHTML = avatarSrc
    ? `<img src="${lpgEscape(avatarSrc)}" alt="${lpgEscape(s.member.name||'Member')}" class="w-16 h-16 rounded-full object-cover ring-2 ring-white/50 shadow-lg" onerror="this.style.display='none';this.nextElementSibling.style.display='flex';"><div class="w-16 h-16 rounded-full items-center justify-center text-xl font-800 hidden ring-2 ring-white/40" style="background-color: ${lpgColor(s.colors.accent)}30; color: #fff; display: none;">${lpgEscape(initials)}</div>`
    : `<div class="w-16 h-16 rounded-full flex items-center justify-center text-xl font-800 ring-2 ring-white/40 shadow-lg" style="background-color: ${lpgColor(s.colors.accent)}30; color: #fff;">${lpgEscape(initials)}</div>`;

  return `<div data-lpg-section="hero" class="member-hero rounded-2xl p-6 mb-6 flex items-center justify-between overflow-hidden shadow-lg">
      <div class="flex items-center gap-4 relative z-10">
        ${avatarHTML}
        <div>
          <div class="text-white/70 text-[11px] font-600 tracking-[0.15em] uppercase">${s._program && s._program.mode === 'b2b' ? 'Business account' : 'Loyalty Member'} · ${lpgEscape(s.member.number||'000000')}</div>
          <div class="text-white text-2xl font-800 mt-1 tracking-tight">${lpgEscape(s.member.name||'Member')}</div>
        </div>
      </div>
      <div class="flex items-center gap-6 relative z-10">
        <div class="text-right">
          <div class="text-white/70 text-[11px] font-600 tracking-[0.15em] uppercase">${s._program ? lpgEscape(s._program.currencies.redeemableName) : 'Perks Points'}</div>
          <div class="flex items-baseline gap-1 justify-end mt-1">
            <span data-lpg-balance="redeemable" class="text-white text-3xl font-900 tracking-tight">${lpgNumber(s.member.points||0).toLocaleString(lpgLocale(s))}</span>
            ${s._program ? '' : '<span class="text-white/80 text-sm font-600">Pts</span>'}
          </div>
        </div>
        <div class="hidden md:flex items-center gap-2" style="color: ${lpgColor(s.colors.accent)};">
          <svg class="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 16.8l-6.2 4.5 2.4-7.4L2 9.4h7.6z"/></svg>
        </div>
      </div>
    </div>`;
}

// ---- TIER PROGRESS ----
function buildTierProgress(s, pointsToNext) {
  if (s._program) {
    const p = s._program, summary = s._summary;
    if (p.capabilities?.tiers === false && !p.qualification?.description) return '';
    if (p.capabilities?.presentationOnly || p.capabilities?.tiers === false) return `<section data-lpg-section="tiers" class="card p-6 mb-8"><h2 class="text-2xl font-800">${lpgEscape(p.member.status || 'Your membership')}</h2><p class="text-sm text-muted">${lpgEscape(p.qualification?.description || 'Explore your membership benefits and opportunities.')}</p>${p.capabilities?.tiers === false ? '' : p.tiers.map(t=>`<p class="mt-3">${lpgEscape(t.name)}</p>`).join('')}</section>`;
    const progress = summary.nextTier ? Math.max(0, Math.min(100, (summary.qualifying-summary.tier.threshold)/(summary.nextTier.threshold-summary.tier.threshold)*100)) : 100;
    return `<section data-lpg-section="tiers" class="card p-6 mb-8">
      <div class="flex items-center justify-between gap-4 mb-6"><div><p class="text-xs text-muted">Your status</p><h2 data-lpg-tier class="text-2xl font-800 text-dark">${lpgEscape(summary.tier.name)}</h2></div>
      <div class="text-right"><strong data-lpg-balance="qualifying" class="text-2xl font-800 text-dark">${lpgNumber(summary.qualifying).toLocaleString(lpgLocale(s))}</strong><p class="text-xs text-muted">${lpgEscape(p.currencies.qualifyingName)}</p></div></div>
      <div class="flex items-center justify-between gap-4 mb-6" style="flex-wrap:wrap">${p.tiers.map((t,i) => `<div data-lpg-tier-index="${i}" class="p-3 text-center"><strong>${lpgEscape(t.name)}</strong><p class="text-xs text-muted">${lpgNumber(t.threshold).toLocaleString(lpgLocale(s))} ${lpgEscape(p.currencies.qualifyingName)}</p></div>`).join('')}</div>
      <div class="h-2.5 bg-gray-100 rounded-full mb-3 overflow-hidden"><div data-lpg-progress class="h-full rounded-full" style="width:${lpgPercent(progress)}%;background:linear-gradient(90deg,${lpgColor(s.colors.accent)},${lpgColor(s.colors.primary)})"></div></div>
      <p data-lpg-progress-text class="text-sm text-muted">${summary.nextTier ? lpgNumber(summary.gap).toLocaleString(lpgLocale(s))+' '+lpgEscape(p.currencies.qualifyingName)+' to '+lpgEscape(summary.nextTier.name) : 'Highest tier achieved'}</p>
    </section>`;
  }
  const tierIcons = [
    `<svg style="width: 28px; height: 28px;" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>`,
    `<svg style="width: 28px; height: 28px;" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 16.8l-6.2 4.5 2.4-7.4L2 9.4h7.6z"/></svg>`,
    `<svg style="width: 28px; height: 28px;" fill="currentColor" viewBox="0 0 24 24"><path d="M5 16L3 5l5.5 5L12 2l3.5 8L21 5l-2 11H5zm14 3c0 .6-.4 1-1 1H6c-.6 0-1-.4-1-1v-1h14v1z"/></svg>`
  ];
  const tiersHTML = s.tiers.map((t,i) => {
    const isActive = i === 0;
    const bg = isActive ? lpgColor(s.colors.accent) : lpgColor(s.colors.primary) + '15';
    const iconColor = isActive ? lpgColor(s.colors.primary) : lpgColor(s.colors.primary) + '80';
    const ring = isActive ? `box-shadow: 0 0 0 3px ${lpgColor(s.colors.accent)}40, 0 6px 16px -6px ${lpgColor(s.colors.accent)}80;` : '';
    return `
              <div class="flex flex-col items-center text-center">
                <div class="w-16 h-16 rounded-full flex items-center justify-center mb-2 transition-transform hover:scale-105" style="background-color: ${bg}; color: ${iconColor}; ${ring}">${tierIcons[i]||tierIcons[2]}</div>
                <span class="text-sm font-700 text-dark">${lpgEscape(t.name)}</span>
                <span class="text-[11px] text-muted mt-0.5">${lpgNumber(t.points||0).toLocaleString(lpgLocale(s))} Tier Points</span>
              </div>`;
  }).join('');

  const nextTierName = s.tiers[1] ? s.tiers[1].name : 'next tier';

  return `<div data-lpg-section="tiers" class="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
      <div class="lg:col-span-2 card p-6">
        <div class="flex items-start justify-between gap-8">
          <div class="flex-1">
            <div class="flex items-end justify-between mb-5">${tiersHTML}</div>
            <div class="relative h-2.5 bg-gray-100 rounded-full mb-3 overflow-hidden">
              <div class="absolute left-0 top-0 h-full rounded-full transition-all" style="width: ${lpgPercent(s.tierProgress)}%; background: linear-gradient(90deg, ${lpgColor(s.colors.accent)}, ${lpgColor(s.colors.primary)});"></div>
              <div class="absolute top-1/2 -translate-y-1/2 w-4 h-4 rounded-full border-2 border-white shadow-md" style="left: calc(${lpgPercent(s.tierProgress)}% - 8px); background-color: ${lpgColor(s.colors.accent)};"></div>
            </div>
            <p class="text-sm text-dark">Earn <span class="font-800" style="color: ${lpgColor(s.colors.primary)};">${lpgNumber(pointsToNext).toLocaleString(lpgLocale(s))} points</span> to reach ${lpgEscape(nextTierName)}! <a href="#" class="font-600 hover:underline ml-2" style="color: ${lpgColor(s.colors.primary)};">View Benefits</a></p>
          </div>
        </div>
      </div>
      <div class="space-y-4">
        <div class="card card-hover p-4 flex gap-3">
          <div class="w-10 h-10 rounded-full bg-warning/10 flex items-center justify-center shrink-0"><svg class="w-5 h-5 text-warning" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/></svg></div>
          <div><p class="text-sm font-700 text-dark">How to retain your ${lpgEscape(s.tiers[0].name)} tier</p><p class="text-xs text-muted mt-1 leading-relaxed">${lpgLabel(s,'retention','Explore the activities and benefits available with your membership.')}</p><a href="#" class="text-xs font-700 hover:underline mt-2 inline-block" style="color: ${lpgColor(s.colors.primary)};">Refer Now →</a></div>
        </div>
        <div class="card card-hover p-4 flex gap-3">
          <div class="w-10 h-10 rounded-full bg-danger/10 flex items-center justify-center shrink-0"><svg class="w-5 h-5 text-danger" fill="currentColor" viewBox="0 0 24 24"><path d="M11.8 10.9c-2.27-.59-3-1.2-3-2.15 0-1.09 1.01-1.85 2.7-1.85 1.78 0 2.44.85 2.5 2.1h2.21c-.07-1.72-1.12-3.3-3.21-3.81V3h-3v2.16c-1.94.42-3.5 1.68-3.5 3.61 0 2.31 1.91 3.46 4.7 4.13 2.5.6 3 1.48 3 2.41 0 .69-.49 1.79-2.7 1.79-2.06 0-2.87-.92-2.98-2.1h-2.2c.12 2.19 1.76 3.42 3.68 3.83V21h3v-2.15c1.95-.37 3.5-1.5 3.5-3.55 0-2.84-2.43-3.81-4.7-4.4z"/></svg></div>
          <div><p class="text-sm font-700 text-dark">${lpgLabel(s,'opportunityTitle','Explore your next reward')}</p><p class="text-xs text-muted mt-1 leading-relaxed">${lpgLabel(s,'opportunityDescription','Discover ways to use your points through eligible rewards.')}</p><a href="#" class="text-xs font-700 hover:underline mt-2 inline-block" style="color: ${lpgColor(s.colors.primary)};">Redeem Now →</a></div>
        </div>
      </div>
    </div>`;
}

// ---- MY PROFILE (Expandable) ----
function buildProfile(s) {
  return `<div data-lpg-section="profile" class="card mb-3 overflow-hidden">
      <button onclick="toggleSection('profile')" aria-expanded="true" aria-controls="profile-content" class="w-full px-6 py-4 flex items-center justify-between hover:bg-gray-50/60 transition-colors">
        <span class="text-base font-700 text-dark">My Profile</span>
        <svg id="profile-chevron" class="w-5 h-5 text-muted chevron-icon rotated" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
      </button>
      <div id="profile-content" class="toggle-content open">
        <div class="px-6 pb-6 border-t border-border pt-5">
          <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
            <div><span class="text-[10px] text-muted uppercase tracking-[0.15em] font-700">Name</span><p class="text-sm font-700 text-dark mt-1.5">${lpgEscape(s.member.name||'Member')}</p></div>
            <div><span class="text-[10px] text-muted uppercase tracking-[0.15em] font-700">Join Date</span><p class="text-sm font-700 text-dark mt-1.5">${lpgEscape(s.member.joinDate||'—')}</p></div>
            <div><span class="text-[10px] text-muted uppercase tracking-[0.15em] font-700">Phone</span><p class="text-sm font-700 text-dark mt-1.5">${lpgEscape(s.member.phone||'—')}</p></div>
            <div><span class="text-[10px] text-muted uppercase tracking-[0.15em] font-700">Email</span><p class="text-sm font-700 text-dark mt-1.5 truncate">${lpgEscape(s.member.email||'—')}</p></div>
          </div>
          <p class="text-xs text-muted mt-5">* Complete your profile to see customized offers & earn perks. <a href="#" class="font-700 hover:underline" style="color: ${lpgColor(s.colors.primary)};">Edit Profile →</a></p>
        </div>
      </div>
    </div>`;
}

// ---- MY BENEFITS (Expandable) ----
function buildBenefits(s) {
  const items = (s.benefits||[]).map(b => {
    const rawCover = b.coverImageData || b.coverImageUrl || '';
    const cover = s.outputTemplate === 'cinematic' ? lpgImageSource(rawCover) : '';
    const imgSrc = lpgImageSource(b.imageData || b.imageUrl);
    const iconInner = imgSrc
      ? `<img src="${lpgEscape(imgSrc)}" alt="${lpgEscape(b.name)}" class="w-full h-full object-cover" onerror="this.style.display='none';this.nextElementSibling.style.display='inline';"><span class="text-lg hidden">${lpgEscape(b.emoji || '✨')}</span>`
      : `<span class="text-lg">${lpgEscape(b.emoji || '✨')}</span>`;
    return `
            <div class="benefit-card ${cover ? 'cj-benefit-has-cover' : ''} flex items-center gap-3 p-3 rounded-xl bg-page-bg transition-colors hover:bg-gray-100">
              <div class="w-10 h-10 rounded-xl flex items-center justify-center shrink-0 overflow-hidden" style="background-color: ${lpgColor(s.colors.primary)}12;">${iconInner}</div>
              <div class="benefit-copy"><p class="text-sm font-700 text-dark">${lpgEscape(b.name)}</p></div>
              ${cover ? `<img class="lpg-benefit-cover" style="${lpgImageStyle(b,'cover')}" src="${lpgEscape(cover)}" alt="" loading="lazy" onerror="this.parentElement.classList.remove('cj-benefit-has-cover');this.remove();">` : ''}
            </div>`;
  }).join('');

  return `<div data-lpg-section="benefits" class="card mb-8 overflow-hidden">
      <button onclick="toggleSection('benefits')" class="w-full px-6 py-4 flex items-center justify-between hover:bg-gray-50/60 transition-colors">
        <span class="text-base font-700 text-dark">${lpgLabel(s,'benefits','My Benefits')}</span>
        <svg id="benefits-chevron" class="w-5 h-5 text-muted chevron-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
      </button>
      <div id="benefits-content" class="toggle-content">
        <div class="px-6 pb-6 border-t border-border pt-5">
          <div class="benefits-grid grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">${items}</div>
          <p class="text-xs text-muted mt-5">Upgrade to enjoy better benefits and exclusive offers. <a href="#" class="font-700 hover:underline" style="color: ${lpgColor(s.colors.primary)};">View All Benefits →</a></p>
        </div>
      </div>
    </div>`;
}

// ---- MY VOUCHERS ----
function buildVouchers(s) {
  if (!s.vouchers || s.vouchers.length === 0) return '';
  const cards = s.vouchers.map((v,i) => {
    const imgSrc = lpgImageSource(v.imageData || v.imageUrl);
    const grad = lpgGradient(v.gradient, VOUCHER_GRADIENTS[i % VOUCHER_GRADIENTS.length]);
    const expiryText = (v.expiry||'').toLowerCase();
    const isExpiring = expiryText.includes('today') || expiryText.includes('expire');
    const expiryStyle = isExpiring ? 'color: #DC2626;' : 'color: #059669;';
    let actionHTML = '';
    if (v.programRewardId && s._program?.capabilities?.presentationOnly) {
      actionHTML = `<button type="button" data-lpg-action="opportunity" data-id="${lpgEscape(v.programRewardId)}" class="btn-primary px-4 py-1.5 text-xs font-700 rounded-full">Explore opportunity</button>`;
    } else if (v.programRewardId) {
      actionHTML = `<span class="text-xs font-700">${lpgEscape(v.actionValue)}</span><button type="button" data-lpg-action="request" data-id="${lpgEscape(v.programRewardId)}" class="btn-primary px-4 py-1.5 text-xs font-700 rounded-full">Redeem reward</button>`;
    } else if (v.actionType === 'points') {
      actionHTML = `<button class="btn-primary px-4 py-1.5 text-xs font-700 rounded-full">${lpgEscape(v.actionValue||'Redeem')}</button>`;
    } else if (v.actionType === 'code') {
      actionHTML = `<div class="px-4 py-1.5 text-xs font-700 rounded-full text-white tracking-wider" style="background-color: ${lpgColor(s.colors.dark)};">${lpgEscape(v.actionValue||'CODE')}</div>`;
    } else {
      actionHTML = `<button class="btn-primary px-4 py-1.5 text-xs font-700 rounded-full">QR Code</button>`;
    }
    return `<div ${v.programRewardId ? `data-program-reward-id="${lpgEscape(v.programRewardId)}"` : ''} class="voucher-card card p-4 flex gap-4 cursor-pointer">
              <div class="w-20 h-20 rounded-xl bg-gradient-to-br from-${grad[0]} to-${grad[1]} flex items-center justify-center shrink-0 overflow-hidden shadow-inner">
                ${imgSrc ? `<img src="${lpgEscape(imgSrc)}" alt="${lpgEscape(v.title)}" style="${lpgImageStyle(v)}" class="w-full h-full object-cover" onerror="this.style.display='none';this.nextElementSibling.style.display='block';"><span class="text-3xl hidden">${lpgEscape(v.emoji||'🎁')}</span>` : `<span class="text-3xl">${lpgEscape(v.emoji||'🎁')}</span>`}
              </div>
              <div class="flex-1 min-w-0">
                <div class="flex items-start justify-between"><div><h3 class="text-sm font-700 text-dark leading-tight">${lpgEscape(v.title)}</h3><p class="text-xs text-muted mt-1">${lpgEscape(v.vendor||'')}</p>${v.description ? `<p class="text-xs text-muted mt-1" style="white-space:pre-wrap">${lpgEscape(v.description)}</p>` : ''}</div></div>
                ${v.expiry ? `<p class="text-[11px] font-700 mt-2 flex items-center gap-1" style="${expiryStyle}"><svg style="width: 12px; height: 12px;" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.2 14.2L11 13V7h1.5v5.2l4.5 2.7-.8 1.3z"/></svg>${lpgEscape(v.expiry)}</p>` : ''}
                <div class="voucher-actions flex items-center gap-2 mt-3">${actionHTML}
                  ${v.programRewardId ? '' : `<button class="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition-colors" title="Copy code"><svg class="w-3.5 h-3.5 text-muted" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg></button>`}
                </div>
              </div>
            </div>`;
  }).join('\n');

  return `<section data-lpg-section="vouchers" id="section-vouchers">
          <div class="flex items-center justify-between mb-4">
            <h2 class="text-lg font-800 text-dark flex items-center gap-2.5 section-title"><span class="w-1 h-6 rounded-full" style="background-color: ${lpgColor(s.colors.primary)};"></span>${lpgLabel(s,'vouchers','My Vouchers')}</h2>
            <a href="#" class="text-sm font-700 hover:underline transition-colors" style="color: ${lpgColor(s.colors.primary)};">View All →</a>
          </div>
          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">${cards}</div>
        </section>`;
}

// ---- MY OFFERS ----
function buildOffers(s) {
  if (!s.offers || s.offers.length === 0) return '';
  const cards = s.offers.map((o,i) => {
    const imgSrc = lpgImageSource(o.imageData || o.imageUrl);
    const grad = lpgGradient(o.gradient, OFFER_GRADIENTS[i % OFFER_GRADIENTS.length]);
    const meta = [];
    if (o.playerCount) meta.push(`<span class="flex items-center gap-1"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z"/></svg>${lpgEscape(o.playerCount)}</span>`);
    if (o.expiry) meta.push(`<span class="flex items-center gap-1"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>${lpgEscape(o.expiry)}</span>`);
    return `<div class="offer-card card overflow-hidden flex">
              <div class="w-48 h-40 bg-gradient-to-br from-${grad[0]} to-${grad[1]} flex items-center justify-center shrink-0 overflow-hidden relative">
                ${imgSrc ? `<img src="${lpgEscape(imgSrc)}" alt="${lpgEscape(o.title)}" style="${lpgImageStyle(o)}" class="w-full h-full object-cover" onerror="this.style.display='none';this.nextElementSibling.style.display='block';"><span class="text-5xl hidden">${lpgEscape(o.emoji||'🎯')}</span>` : `<span class="text-6xl drop-shadow-lg">${lpgEscape(o.emoji||'🎯')}</span>`}
                <div class="absolute inset-0" style="background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.25) 100%);"></div>
              </div>
              <div class="p-5 flex-1 flex flex-col justify-between">
                <div>
                  <h3 class="text-base font-800 text-dark leading-tight">${lpgEscape(o.title)}</h3>
                  <p class="text-sm text-muted mt-1.5 leading-relaxed">${lpgEscape(o.description||'')}</p>
                  ${meta.length ? `<div class="flex items-center gap-4 mt-3 text-[11px] font-600 text-muted">${meta.join('')}</div>` : ''}
                </div>
                <button class="btn-primary self-start mt-4 px-6 py-2 text-sm font-700 rounded-full">${lpgEscape(o.cta||'Learn More')}</button>
              </div>
            </div>`;
  }).join('\n');

  return `<section data-lpg-section="offers" id="section-offers">
          <div class="flex items-center justify-between mb-4">
            <h2 class="text-lg font-800 text-dark flex items-center gap-2.5 section-title"><span class="w-1 h-6 rounded-full" style="background-color: ${lpgColor(s.colors.primary)};"></span>${lpgLabel(s,'offers','My Offers & Promotions')}</h2>
            <a href="#" class="text-sm font-700 hover:underline" style="color: ${lpgColor(s.colors.primary)};">View All →</a>
          </div>
          <div class="space-y-4">${cards}</div>
        </section>`;
}

// ---- EARN MORE ----
function buildEarnMore(s) {
  if (!s.earnMore || s.earnMore.length === 0) return '';
  const icons = [
    '<svg class="w-5 h-5 text-primary" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>',
    '<svg class="w-5 h-5 text-primary" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z"/></svg>',
    '<svg class="w-5 h-5 text-primary" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>',
    '<svg class="w-5 h-5 text-primary" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z"/></svg>'
  ];
  const cards = s.earnMore.map((e,i) => {
    if (e.programRuleId && e.rule) {
      const rule = e.rule;
      const image = lpgImageSource(e.imageData || e.imageUrl);
      const icon = e.emoji ? `<span class="text-xl" aria-hidden="true">${lpgEscape(e.emoji)}</span>` : icons[i % icons.length];
      return `<article data-program-rule-id="${lpgEscape(rule.id)}" class="earn-card card p-4">
        ${image ? `<img src="${lpgEscape(image)}" alt="${lpgEscape(e.title)}" class="w-full h-32 rounded-xl object-cover mb-3" onerror="this.hidden=true;">` : ''}
        <div class="flex items-start gap-3">
          <div class="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style="background-color: ${lpgColor(s.colors.primary)}15; color: ${lpgColor(s.colors.primary)};">${icon}</div>
          <div class="flex-1 min-w-0">
            <h3 class="text-sm font-700 text-dark leading-tight"><button type="button" class="w-full flex items-start justify-between gap-3 text-left" data-lpg-action="activity" data-id="${lpgEscape(rule.id)}" aria-label="${lpgEscape('Explore ' + (e.title || 'activity'))}"><span>${lpgEscape(e.title)}</span><svg class="w-5 h-5 text-muted shrink-0" aria-hidden="true" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg></button></h3>
            <p data-lpg-activity-description class="text-xs text-muted mt-1 leading-relaxed">${lpgEscape(e.description || '')}</p>
          </div>
        </div>
      </article>`;
    }
    if (e.hasCodeInput) {
      return `<div class="earn-card card p-4 cursor-pointer">
              <div class="flex items-start gap-3">
                <div class="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style="background-color: ${lpgColor(s.colors.primary)}15; color: ${lpgColor(s.colors.primary)};">${icons[i%icons.length]}</div>
                <div class="flex-1"><h3 class="text-sm font-700 text-dark">${lpgEscape(e.title)}</h3></div>
              </div>
              <div class="flex items-center gap-2 mt-3">
                <input type="text" placeholder="Enter your code" class="flex-1 px-3 py-2 text-xs border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary">
                <button class="px-4 py-2 text-white text-xs font-700 rounded-lg transition-colors" style="background-color: ${lpgColor(s.colors.dark)};" onmouseover="this.style.opacity=0.9" onmouseout="this.style.opacity=1">Enter</button>
              </div>
            </div>`;
    }
    return `<div class="earn-card card p-4 flex items-start gap-3 cursor-pointer">
              <div class="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style="background-color: ${lpgColor(s.colors.primary)}15; color: ${lpgColor(s.colors.primary)};">${icons[i%icons.length]}</div>
              <div class="flex-1"><h3 class="text-sm font-700 text-dark leading-tight">${lpgEscape(e.title)}</h3><p class="text-xs text-muted mt-1 leading-relaxed">${lpgEscape(e.description||'')}</p></div>
              <svg class="w-5 h-5 text-muted shrink-0 mt-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
            </div>`;
  }).join('\n');

  return `<section data-lpg-section="earn" id="section-earn-more">
          <div class="flex items-center justify-between mb-4">
            <h2 class="text-lg font-800 text-dark flex items-center gap-2.5 section-title"><span class="w-1 h-6 rounded-full" style="background-color: ${lpgColor(s.colors.primary)};"></span>${lpgLabel(s,'earn','Earn More')}</h2>
          </div>
          <div class="earn-grid grid grid-cols-1 sm:grid-cols-2 gap-4">${cards}</div>
        </section>`;
}

// ---- COMPLETE PROFILE & EARN ----
function buildProfileTasks(s) {
  if (!s.profileTasks || s.profileTasks.length === 0) return '';
  const tasks = s.profileTasks.map(t => `
            <div class="flex items-start justify-between gap-3">
              <p class="text-xs text-muted flex-1 leading-relaxed">${lpgEscape(t.description)}</p>
              <button class="btn-ghost px-4 py-1.5 text-xs font-700 rounded-full shrink-0">${lpgEscape(t.cta)}</button>
            </div>`).join('');

  return `<section data-lpg-section="profile-tasks" id="section-profile-tasks" class="card p-5">
          <h3 class="text-base font-800 text-dark mb-4 section-title">Complete Profile &amp; Earn</h3>
          <div class="mb-2">
            <div class="flex items-center justify-between text-xs text-muted mb-1.5"><span>Your profile is <span class="font-800" style="color: ${lpgColor(s.colors.primary)};">60%</span> completed</span></div>
            <div class="h-2 bg-gray-100 rounded-full overflow-hidden"><div class="h-full rounded-full transition-all" style="width: 60%; background: linear-gradient(90deg, ${lpgColor(s.colors.accent)}, ${lpgColor(s.colors.primary)});"></div></div>
          </div>
          <div class="space-y-4 mt-5">${tasks}</div>
        </section>`;
}

// ---- MY BADGES ----
function buildBadges(s) {
  if (!s.badges || s.badges.length === 0) return '';
  const items = s.badges.map(b => {
    const c = /^(?:slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)$/.test(b.color || '') ? b.color : 'amber';
    const imgSrc = lpgImageSource(b.imageData || b.imageUrl);
    const inner = imgSrc
      ? `<img src="${lpgEscape(imgSrc)}" alt="${lpgEscape(b.name)}" class="w-full h-full object-cover" onerror="this.style.display='none';this.nextElementSibling.style.display='inline';"><span class="text-2xl drop-shadow-sm hidden">${lpgEscape(b.emoji||'⭐')}</span>`
      : `<span class="text-2xl drop-shadow-sm">${lpgEscape(b.emoji||'⭐')}</span>`;
    return `<div class="flex flex-col items-center gap-2 group">
              <div class="w-16 h-16 rounded-full bg-gradient-to-br from-${c}-400 to-${c}-600 flex items-center justify-center overflow-hidden transition-transform group-hover:scale-105" style="box-shadow: 0 0 0 3px #fff, 0 0 0 5px rgb(var(--tw-${c}-300, 251 191 36 / 0.7) / 0.6), 0 8px 16px -6px rgba(0,0,0,0.15);">${inner}</div>
              <span class="text-[11px] font-700 text-center text-dark leading-tight">${lpgEscape(b.name||'Badge').replace(/ /g,'<br>')}</span>
            </div>`;
  }).join('');

  return `<section data-lpg-section="badges" id="section-badges">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-base font-800 text-dark section-title">${lpgLabel(s,'badges','My Badges')} (${s.badges.length})</h3>
            <a href="#" class="text-sm font-700 hover:underline" style="color: ${lpgColor(s.colors.primary)};">View All →</a>
          </div>
          <div class="flex items-center justify-start gap-6 flex-wrap">${items}</div>
        </section>`;
}

// ---- MY SOCIAL CLUBS ----
function buildClubs(s) {
  if (!s.clubs || s.clubs.length === 0) return '';
  const items = s.clubs.map((c,i) => {
    const imgSrc = lpgImageSource(c.imageData || c.imageUrl);
    const grad = lpgGradient(c.gradient, CLUB_GRADIENTS[i % CLUB_GRADIENTS.length]);
    return `<div class="card card-hover p-4 flex gap-3 cursor-pointer">
              <div class="w-14 h-14 rounded-xl bg-gradient-to-br from-${grad[0]} to-${grad[1]} flex items-center justify-center shrink-0 overflow-hidden shadow-inner">
                ${imgSrc ? `<img src="${lpgEscape(imgSrc)}" alt="${lpgEscape(c.name)}" class="w-full h-full object-cover" onerror="this.style.display='none';this.nextElementSibling.style.display='block';"><span class="text-2xl hidden">${lpgEscape(c.emoji||'👥')}</span>` : `<span class="text-2xl drop-shadow">${lpgEscape(c.emoji||'👥')}</span>`}
              </div>
              <div class="min-w-0">
                <h4 class="text-sm font-800 text-dark leading-tight">${lpgEscape(c.name)}</h4>
                <p class="text-xs text-muted mt-1 leading-relaxed line-clamp-2">${lpgEscape(c.description||'')}</p>
                <p class="text-[11px] text-muted mt-2 flex items-center gap-1 font-600"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z"/></svg>${lpgNumber(c.memberCount||0).toLocaleString(lpgLocale(s))} Members</p>
              </div>
            </div>`;
  }).join('');

  return `<section data-lpg-section="clubs" id="section-clubs">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-base font-800 text-dark section-title">${lpgLabel(s,'clubs','My Social Clubs')} (${s.clubs.length})</h3>
            <a href="#" class="text-sm font-700 hover:underline" style="color: ${lpgColor(s.colors.primary)};">View All →</a>
          </div>
          <div class="space-y-4">${items}</div>
        </section>`;
}

// ---- UPSELL BANNER ----
function buildUpsell(s) {
  if (!s.upsell || !s.upsell.title) return '';
  const u = s.upsell;

  const bgColor = lpgColor(u.bgColor, '#7C1D1D');
  const bgColorDark = darkenColor(bgColor, 15);
  const bgImage = lpgCssImage(u.bgImageData || u.bgImageUrl);
  const titleColor = lpgColor(u.titleColor, lpgColor(s.colors.accent));
  const subtitleColor = lpgColor(u.subtitleColor, lpgColor('#FFFFFF'));
  const priceColor = lpgColor(u.priceColor, lpgColor('#FFFFFF'));
  const periodColor = lpgColor(u.periodColor, lpgColor('rgba(255,255,255,0.80)'));

  // When there's a bg image, put a subtle scrim over it so text stays legible.
  const bgLayers = bgImage
    ? `background-image: linear-gradient(135deg, ${bgColor}CC 0%, ${bgColorDark}CC 100%), url('${bgImage}'); background-size: cover, cover; background-position: center, center;`
    : `background-image: linear-gradient(135deg, ${bgColor} 0%, ${bgColorDark} 100%);`;

  return `<section data-lpg-section="upsell" id="section-upsell" class="card overflow-hidden">
          <div class="relative p-7 text-center overflow-hidden" style="${lpgEscape(bgLayers)}">
            <div class="absolute inset-0 opacity-20" style="background-image: radial-gradient(circle at 20% 20%, rgba(255,255,255,0.2), transparent 40%), radial-gradient(circle at 80% 80%, rgba(255,255,255,0.15), transparent 40%);"></div>
            <div class="relative">
              <div class="text-2xl font-900 mb-1 italic" style="color: ${titleColor}; font-family: 'Georgia', serif; text-shadow: 0 2px 4px rgba(0,0,0,0.3);">${lpgEscape(u.title)}</div>
              <div class="text-xs font-800 uppercase tracking-[0.2em] mt-2" style="color: ${subtitleColor};">${lpgEscape(u.subtitle||'')}</div>
              ${u.price ? `<div class="mt-4 flex items-start justify-center gap-1" style="color: ${priceColor};">${String(u.price).startsWith('$') ? '<span class="text-2xl font-700 mt-2">$</span>' : ''}<span class="text-6xl font-900 leading-none">${lpgEscape(String(u.price).replace(/^\$/,''))}</span></div>` : ''}
              ${u.price && u.period ? `<div class="text-[11px] mt-2 uppercase tracking-[0.15em] font-700" style="color: ${periodColor};">${lpgEscape(u.period)}</div>` : ''}
            </div>
          </div>
          <div class="p-5 text-center">
            <p class="text-sm text-dark font-500 mb-4 leading-relaxed">${lpgEscape(u.tagline||'')}</p>
            <button class="btn-primary w-full py-3 text-sm font-800 rounded-full uppercase tracking-wider">${lpgEscape(u.cta||'Upgrade')}</button>
            <div class="flex items-center justify-center gap-2 mt-4"><div class="w-6 h-1.5 rounded-full" style="background-color: ${lpgColor(s.colors.primary)};"></div><div class="w-1.5 h-1.5 rounded-full bg-gray-300"></div><div class="w-1.5 h-1.5 rounded-full bg-gray-300"></div></div>
          </div>
        </section>`;
}

